      <button type="button" matButton="filled" data-testid="movies-retry-button" (click)="retry()">Retry</button>
    </div>
  } @else {
    <div class="movie-list" data-testid="movie-list">
      @for (item of current.movies; track item.movie.id) {
        <article class="movie-card" data-testid="movie-card" [attr.data-movie-id]="item.movie.id">
          <h2 data-testid="movie-title">{{ item.movie.title }}</h2>
          <p class="movie-meta">
            <span data-testid="movie-genre">{{ item.movie.genre }}</span>
            <span data-testid="movie-runtime">{{ item.movie.runtimeMinutes }} min</span>
            <span data-testid="movie-format">{{ item.movie.format }}</span>
          </p>
          <div class="screening-buttons">
            @for (screening of item.screenings; track screening.id) {
              <button
                type="button"
                matButton="outlined"
                data-testid="screening-button"
                [attr.data-screening-id]="screening.id"
                (click)="openScreening(screening.id)"
              >
                {{ screening.time }}
              </button>
            }
          </div>
        </article>
      }
    </div>
    @if (current.movies.length === 0) {
      <p class="movies-empty" data-testid="movies-empty">No screenings on this day</p>
    }
  }
</main>
