export type SeatState = 'available' | 'unavailable' | 'accessible';

export interface SeatCell {
  kind: 'seat';
  row: number;
  column: number;
  state: SeatState;
}

export interface CouchCell {
  kind: 'couch';
  row: number;
  columnStart: number;
  columnEnd: number;
  state: 'available' | 'unavailable';
}

export interface AisleCell {
  kind: 'aisle';
  row: number;
}

/** The space left of the seats in rows 1–10, where the entrance is. */
export interface EntranceCell {
  kind: 'entrance';
}

export type AuditoriumCell = SeatCell | CouchCell | AisleCell | EntranceCell;

export interface AuditoriumRow {
  row: number;
  cells: AuditoriumCell[];
}

const ROW_COUNT = 15;
const LAST_ENTRANCE_ROW = 10;
const COUCH_ROW = 15;
const ACCESSIBLE_ROW = 1;
const ACCESSIBLE_FIRST_COLUMN = 10;
const ACCESSIBLE_LAST_COLUMN = 15;

/**
 * Builds the auditorium from top (row 1, next to the screen) to bottom. Each row lists its
 * cells from left to right: the left block (columns 1–4, or the entrance in rows 1–10), an
 * aisle, columns 5–20, an aisle and columns 21–24. Row 15 is made of couches.
 */
export function buildAuditorium(occupiedSeats: readonly string[]): AuditoriumRow[] {
  const occupied = new Set(occupiedSeats);
  return Array.from({ length: ROW_COUNT }, (_, index) => {
    const row = index + 1;
    const left: AuditoriumCell[] =
      row <= LAST_ENTRANCE_ROW ? [{ kind: 'entrance' }] : blockCells(row, 1, 4, occupied);
    return {
      row,
      cells: [
        ...left,
        { kind: 'aisle', row },
        ...blockCells(row, 5, 20, occupied),
        { kind: 'aisle', row },
        ...blockCells(row, 21, 24, occupied),
      ],
    };
  });
}

export function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

function blockCells(row: number, firstColumn: number, lastColumn: number, occupied: ReadonlySet<string>): AuditoriumCell[] {
  const cells: AuditoriumCell[] = [];
  for (let column = firstColumn; column <= lastColumn; ) {
    if (row === COUCH_ROW) {
      cells.push(couchCell(row, column, occupied));
      column += 2;
    } else {
      cells.push(seatCell(row, column, occupied));
      column += 1;
    }
  }
  return cells;
}

function seatCell(row: number, column: number, occupied: ReadonlySet<string>): SeatCell {
  let state: SeatState = 'available';
  if (occupied.has(seatId(row, column))) {
    state = 'unavailable';
  } else if (isAccessible(row, column)) {
    state = 'accessible';
  }
  return { kind: 'seat', row, column, state };
}

function couchCell(row: number, columnStart: number, occupied: ReadonlySet<string>): CouchCell {
  const columnEnd = columnStart + 1;
  const isOccupied = occupied.has(seatId(row, columnStart)) || occupied.has(seatId(row, columnEnd));
  return { kind: 'couch', row, columnStart, columnEnd, state: isOccupied ? 'unavailable' : 'available' };
}

function isAccessible(row: number, column: number): boolean {
  return row === ACCESSIBLE_ROW && column >= ACCESSIBLE_FIRST_COLUMN && column <= ACCESSIBLE_LAST_COLUMN;
}

import { Component, computed, inject } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { ActivatedRoute, Router } from '@angular/router';
import { EMPTY, Observable, catchError, map, switchMap } from 'rxjs';
import { CinemaApi } from '../cinema-api.service';
import { formatShowDate } from '../dates';
import { Movie, Screening } from '../models';
import { buildAuditorium } from './auditorium';

interface LoadedScreening {
  screening: Screening;
  movie: Movie;
}

@Component({
  selector: 'app-seat-selection',
  templateUrl: './seat-selection.html',
  styleUrl: './seat-selection.scss',
})
export class SeatSelection {
  private readonly api = inject(CinemaApi);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);

  private readonly loaded = toSignal(
    this.route.paramMap.pipe(
      map((params) => params.get('id') ?? ''),
      switchMap((id) => this.load(id)),
    ),
    { initialValue: null },
  );

  /** Null while the screening is loading; a failed load redirects to `/`. */
  readonly page = computed(() => {
    const current = this.loaded();
    if (!current) {
      return null;
    }
    return {
      showDate: formatShowDate(current.screening.date, current.screening.time),
      rows: buildAuditorium(current.screening.occupiedSeats),
    };
  });

  private load(id: string): Observable<LoadedScreening> {
    return this.api.screening(id).pipe(
      switchMap((screening) =>
        this.api.movie(screening.movieId).pipe(map((movie) => ({ screening, movie }))),
      ),
      catchError(() => {
        void this.router.navigate(['/']);
        return EMPTY;
      }),
    );
  }
}

.seat-selection-page {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  padding: 24px;
  text-align: center;
}

.page-title {
  margin: 0;
  font-size: 1.75rem;
}

.show-date {
  margin: 0;
  color: rgba(0, 0, 0, 0.6);
}

// The auditorium is as wide as its seat map; the text above and the screen bar match that width.
.auditorium {
  display: flex;
  flex-direction: column;
  gap: 12px;
  width: max-content;
  margin-top: 8px;
}

.seat-limit {
  margin: 0;
}

.screen {
  padding: 6px 0;
  border-radius: 0 0 50% 50% / 0 0 12px 12px;
  background: #e0e0e0;
  font-size: 0.8rem;
  letter-spacing: 6px;
}

.seat-map {
  --seat: 32px;
  --gap: 4px;
  --aisle: calc(2 * var(--seat) + var(--gap));
  --label: 32px;

  display: flex;
  flex-direction: column;
  gap: var(--gap);
}

// Tracks: row label, columns 1–4, aisle, columns 5–20, aisle, columns 21–24, row label.
// Couches span two tracks, so a couch is one wide element over two columns.
.seat-row {
  display: grid;
  grid-template-columns:
    var(--label)
    repeat(4, var(--seat))
    var(--aisle)
    repeat(16, var(--seat))
    var(--aisle)
    repeat(4, var(--seat))
    var(--label);
  column-gap: var(--gap);
  align-items: center;
}

.row-label {
  font-size: 0.8rem;
  color: rgba(0, 0, 0, 0.6);
}

.entrance {
  grid-column: span 4;
}

.seat,
.couch {
  height: var(--seat);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px 6px 2px 2px;
  color: #fff;
  font-size: 0.75rem;
  font-weight: 500;
  user-select: none;

  &[data-state='available'] {
    background-color: #2e7d32;
  }

  &[data-state='unavailable'] {
    background-color: #c62828;
  }

  &[data-state='accessible'] {
    background-color: #1565c0;
  }
}

.couch {
  grid-column: span 2;
}

