<main class="movie-list-page">
  <div class="day-picker" data-testid="day-picker">
    @for (day of dayButtons; track day.iso) {
      <button
        type="button"
        data-testid="day-button"
        [matButton]="isSelected(day) ? 'filled' : 'outlined'"
        [attr.data-date]="day.iso"
        [attr.data-selected]="isSelected(day) ? 'true' : 'false'"
        (click)="chooseDate(day.iso)"
      >
        {{ day.label }}
      </button>
    }

    <mat-form-field class="date-field">
      <mat-label>Choose another date</mat-label>
      <input
        matInput
        data-testid="date-picker"
        [matDatepicker]="picker"
        [min]="todayPickerMin"
        [value]="pickerValue()"
        (dateChange)="onDatePicked($event)"
      />
      <mat-datepicker-toggle matIconSuffix [for]="picker" />
      <mat-datepicker #picker />
    </mat-form-field>
  </div>

  @let current = state();
  @if (current.status === 'loading') {
    <div class="movies-state" data-testid="movies-loading">
      <mat-spinner diameter="32" />
      <p>Loading…</p>
    </div>
  } @else if (current.status === 'error') {
    <div class="movies-state">
      <p data-testid="movies-error">Failed to load movies</p>
      <button type="button" matButton="filled" data-testid="movies-retry-button" (click)="retry()">Retry</button>
    </div>
  } @else {
    <div class="movie-list" data-testid="movie-list">
      @for (item of current.movies; track item.movie.id) {
        <article class="movie-card" data-testid="movie-card" [attr.data-movie-id]="item.movie.id">
          <h2 data-testid="movie-title">{{ item.movie.title }}</h2>
          <p class="movie-meta">
            <span data-testid="movie-genre">{{ item.movie.genre }}</span>
            <span data-testid="movie-runtime">{{ item.movie.runtimeMinutes }} min</span>
            <span data-testid="movie-format">{{ item.movie.format }}</span>
          </p>
          <div class="screening-buttons">
            @for (screening of item.screenings; track screening.id) {
              <button
                type="button"
                matButton="outlined"
                data-testid="screening-button"
                [attr.data-screening-id]="screening.id"
                (click)="openScreening(screening.id)"
              >
                {{ screening.time }}
              </button>
            }
          </div>
        </article>
      }
    </div>
    @if (current.movies.length === 0) {
      <p class="movies-empty" data-testid="movies-empty">No screenings on this day</p>
    }
  }
