<main class="seat-selection-page">
  @let current = page(); @if (current) {
  <h1 class="page-title" data-testid="seat-map-title">Choose your seats</h1>
  <p class="show-date" data-testid="seat-map-subtitle">Show Date: {{ current.showDate }}</p>

  <section class="auditorium">
    <p class="seat-limit" data-testid="seat-limit-info">
      You can reserve up to 10 seats per reservation
    </p>
    <div class="screen" data-testid="screen-indicator">SCREEN</div>

    <div class="seat-map" data-testid="seat-map">
      @for (row of current.rows; track row.row) {
      <div class="seat-row" data-testid="seat-row" [attr.data-row]="row.row">
        <span class="row-label" data-testid="row-label-left" [attr.data-row]="row.row"
          >{{ row.row }}</span
        >
        @for (cell of row.cells; track $index) { @switch (cell.kind) { @case ('entrance') {
        <div class="entrance" aria-hidden="true"></div>
        } @case ('aisle') {
        <div class="aisle" data-testid="aisle" [attr.data-row]="cell.row"></div>
        } @case ('seat') {
        <!-- prettier-ignore -->
        <button
          type="button"
          class="seat"
          data-testid="seat"
          [attr.data-row]="cell.row"
          [attr.data-column]="cell.column"
          [attr.data-state]="displayState(cell)"
          (click)="toggle(cell)"
        >{{ cell.column }}</button>
        } @case ('couch') {
        <!-- prettier-ignore -->
        <button
          type="button"
          class="couch"
          data-testid="couch"
          [attr.data-row]="cell.row"
          [attr.data-column-start]="cell.columnStart"
          [attr.data-column-end]="cell.columnEnd"
          [attr.data-state]="displayState(cell)"
          (click)="toggle(cell)"
        >{{ cell.columnStart }}-{{ cell.columnEnd }}</button>
        } } }
        <span class="row-label" data-testid="row-label-right" [attr.data-row]="row.row"
          >{{ row.row }}</span
        >
      </div>
      }
    </div>
  </section>

  <ul class="legend" data-testid="legend">
