import { Component, computed, inject, signal } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { ActivatedRoute, Router } from '@angular/router';
import { EMPTY, catchError, map, switchMap } from 'rxjs';
import { BookingStore, TicketItem, ticketsFor } from '../booking';
import { CinemaApi } from '../cinema-api.service';
import { formatPrice } from '../pricing';

@Component({
  selector: 'app-summary',
  imports: [MatButtonModule],
  templateUrl: './summary.html',
  styleUrl: './summary.scss',
})
export class Summary {
  private readonly api = inject(CinemaApi);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly bookings = inject(BookingStore);

  readonly formatPrice = formatPrice;

  /** Seat identifiers of the booking; the route guard ensures a booking exists for this screening. */
  private readonly seats = signal<string[]>(this.bookings.read()?.seats ?? []);

  /** Null while loading; a failed load redirects to `/`. */
  readonly loaded = toSignal(
    this.route.paramMap.pipe(
      map((params) => params.get('id') ?? ''),
      switchMap((id) =>
        this.api.screeningWithMovie(id).pipe(
          catchError(() => {
            void this.router.navigate(['/']);
            return EMPTY;
          }),
        ),
      ),
    ),
    { initialValue: null },
  );

  readonly items = computed(() => ticketsFor(this.seats()));

  readonly total = computed(() => this.items().reduce((sum, item) => sum + item.price, 0));

  /** Removes a seat or couch from the booking; removing the last one returns to the seat map. */
  remove(item: TicketItem): void {
    const booking = this.bookings.read();
    if (!booking) {
      return;
    }
    const seats = booking.seats.filter((id) => !item.seatIds.includes(id));
    this.bookings.write({ ...booking, seats });
    this.seats.set(seats);
    if (seats.length === 0) {
      void this.router.navigate(['/screenings', booking.screeningId, 'seats']);
    }
  }

  back(): void {
    this.navigateTo('seats');
  }

  confirm(): void {
    this.navigateTo('checkout');
  }

  private navigateTo(step: 'seats' | 'checkout'): void {
    const screening = this.loaded()?.screening;
    if (screening) {
      void this.router.navigate(['/screenings', screening.id, step]);
    }
  }
}

.summary-page {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  padding: 24px;
}

.page-title {
  margin: 0;
  font-size: 1.75rem;
}

.items {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 640px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 16px;
  border: 1px solid rgba(0, 0, 0, 0.12);
  border-radius: 8px;
}

.item-title {
  flex: 1;
  font-weight: 500;
}

.item-field {
  white-space: nowrap;
}

.total {
  margin: 0;
  font-size: 1.1rem;
  font-weight: 500;
}

.actions {
  display: flex;
  gap: 16px;
}

import { ticketsFor } from './booking';
import { formatPrice, seatPrice } from './pricing';

describe('ticketsFor', () => {
  it('lists seats and couches ordered by row and then by column', () => {
    const items = ticketsFor(['R15C3', 'R7C12', 'R15C1', 'R7C11', 'R1C10']);
    expect(items.map((item) => [item.row, item.seat])).toEqual([
      [1, '10'],
      [7, '11'],
      [7, '12'],
      [15, 'Couch 1-2'],
      [15, 'Couch 3-4'],
    ]);
  });

  it('describes a couch by both columns and lists its two identifiers', () => {
    const [couch] = ticketsFor(['R15C5', 'R15C6']);
    expect(couch.seat).toBe('Couch 5-6');
    expect(couch.seatIds).toEqual(['R15C5', 'R15C6']);
  });

  it('prices seats by row and a couch as one unit', () => {
    const items = ticketsFor(['R3C7', 'R8C7', 'R12C7', 'R15C1', 'R15C2']);
    expect(items.map((item) => item.price)).toEqual([25, 32, 39, 89]);
  });

  it('prices the accessible seats of row 1 like the rest of rows 1 to 5', () => {
    expect(ticketsFor(['R1C10'])[0].price).toBe(25);
    expect(seatPrice(5)).toBe(25);
  });

  it('prints prices with two decimals and the PLN suffix', () => {
    expect(formatPrice(25)).toBe('25.00 PLN');
    expect(formatPrice(121)).toBe('121.00 PLN');
  });
});

