  justify-content: space-between;
  gap: 16px;
  padding: 12px 16px;
  border: 1px solid rgba(0, 0, 0, 0.12);
  border-radius: 8px;
}

.item-title {
  flex: 1;
  font-weight: 500;
}

.item-field {
  white-space: nowrap;
