    30	export interface AuditoriumRow {
    31	  row: number;
    32	  cells: AuditoriumCell[];
    33	}
    34	
    35	const ROW_COUNT = 15;
    36	const LAST_ENTRANCE_ROW = 10;
    37	export const COUCH_ROW = 15;
    38	const ACCESSIBLE_ROW = 1;
    39	const ACCESSIBLE_FIRST_COLUMN = 10;
    40	const ACCESSIBLE_LAST_COLUMN = 15;
    41	
    42	/**
    43	 * Builds the auditorium from top (row 1, next to the screen) to bottom. Each row lists its
    44	 * cells from left to right: the left block (columns 1–4, or the entrance in rows 1–10), an
    45	 * aisle, columns 5–20, an aisle and columns 21–24. Row 15 is made of couches.
    46	 */
    47	export function buildAuditorium(occupiedSeats: readonly string[]): AuditoriumRow[] {
    48	  const occupied = new Set(occupiedSeats);
    49	  return Array.from({ length: ROW_COUNT }, (_, index) => {
    50	    const row = index + 1;
    51	    const left: AuditoriumCell[] =
    52	      row <= LAST_ENTRANCE_ROW ? [{ kind: 'entrance' }] : blockCells(row, 1, 4, occupied);
    53	    return {
    54	      row,
    55	      cells: [
    56	        ...left,
    57	        { kind: 'aisle', row },
    58	        ...blockCells(row, 5, 20, occupied),
    59	        { kind: 'aisle', row },
    60	        ...blockCells(row, 21, 24, occupied),
    61	      ],
    62	    };
    63	  });
    64	}
    65	
    66	export function seatId(row: number, column: number): string {
    67	  return `R${row}C${column}`;
    68	}
    69	
    70	/** The seat identifiers a seat or couch occupies: one for a seat, two for a couch. */
    71	export function seatIdsOf(cell: SeatCell | CouchCell): string[] {
    72	  return cell.kind === 'seat'
    73	    ? [seatId(cell.row, cell.column)]
    74	    : [seatId(cell.row, cell.columnStart), seatId(cell.row, cell.columnEnd)];
    75	}
    76	
    77	function blockCells(
    78	  row: number,
    79	  firstColumn: number,
    80	  lastColumn: number,
    81	  occupied: ReadonlySet<string>,
    82	): AuditoriumCell[] {
    83	  const cells: AuditoriumCell[] = [];
    84	  for (let column = firstColumn; column <= lastColumn;) {
    85	    if (row === COUCH_ROW) {
    86	      cells.push(couchCell(row, column, occupied));
    87	      column += 2;
    88	    } else {
    89	      cells.push(seatCell(row, column, occupied));
    90	      column += 1;
    91	    }
    92	  }
    93	  return cells;
    94	}
    95	
    96	function seatCell(row: number, column: number, occupied: ReadonlySet<string>): SeatCell {
    97	  let state: SeatState = 'available';
    98	  if (occupied.has(seatId(row, column))) {
    99	    state = 'unavailable';
   100	  } else if (isAccessible(row, column)) {
   101	    state = 'accessible';
   102	  }
   103	  return { kind: 'seat', row, column, state };
   104	}
   105	
   106	function couchCell(row: number, columnStart: number, occupied: ReadonlySet<string>): CouchCell {
   107	  const columnEnd = columnStart + 1;
   108	  const isOccupied = occupied.has(seatId(row, columnStart)) || occupied.has(seatId(row, columnEnd));
   109	  return {
   110	    kind: 'couch',
   111	    row,
   112	    columnStart,
   113	    columnEnd,
   114	    state: isOccupied ? 'unavailable' : 'available',
   115	  };
   116	}
   117	
   118	function isAccessible(row: number, column: number): boolean {
   119	  return (
   120	    row === ACCESSIBLE_ROW && column >= ACCESSIBLE_FIRST_COLUMN && column <= ACCESSIBLE_LAST_COLUMN
   121	  );
   122	}
