     9	import { formatPrice } from '../pricing';
    10	import { Toast } from '../toast';
    11	import {
    12	  CHECKOUT_FIELDS,
    13	  CheckoutField,
    14	  CheckoutValues,
    15	  EMPTY_CHECKOUT,
    16	  validateCheckout,
    17	} from './checkout-rules';
    18	
    19	type TextField = Exclude<CheckoutField, 'terms'>;
    20	
    21	@Component({
    22	  selector: 'app-checkout',
    23	  imports: [MatButtonModule, MatCheckboxModule, MatFormFieldModule, MatInputModule],
    24	  templateUrl: './checkout.html',
    25	  styleUrl: './checkout.scss',
    26	})
    27	export class Checkout {
    28	  private readonly api = inject(CinemaApi);
    29	  private readonly router = inject(Router);
    30	  private readonly toast = inject(Toast);
    31	  private readonly bookings = inject(BookingStore);
    32	
    33	  /** The route guard ensures a booking in progress exists for this screen. */
    34	  private readonly initial = this.bookings.read();
    35	
    36	  readonly formatPrice = formatPrice;
    37	
    38	  /** The form values; saved in the booking as they change (section 7.1). */
    39	  readonly values = signal<CheckoutValues>(this.initial?.checkout ?? EMPTY_CHECKOUT);
    40	
    41	  /** Fields that have been left at least once, or that `Pay` has marked. */
    42	  private readonly touched = signal<ReadonlySet<CheckoutField>>(new Set());
    43	
    44	  /** True while the reservation request is in flight. */
    45	  readonly submitting = signal(false);
    46	
    47	  private readonly errors = computed(() => validateCheckout(this.values()));
    48	
    49	  readonly total = ticketsFor(this.initial?.seats ?? []).reduce((sum, item) => sum + item.price, 0);
    50	
    51	  /** The message of a field, shown only once the field has been left. */
    52	  message(field: CheckoutField): string | null {
    53	    return this.touched().has(field) ? (this.errors()[field] ?? null) : null;
    54	  }
    55	
    56	  onInput(field: TextField, event: Event): void {
    57	    this.setValue(field, (event.target as HTMLInputElement).value);
    58	  }
    59	
    60	  onTermsChange(checked: boolean): void {
    61	    this.setValue('terms', checked);
    62	    this.touch('terms');
    63	  }
    64	
    65	  touch(field: CheckoutField): void {
    66	    this.touched.update((fields) => new Set(fields).add(field));
    67	  }
    68	
    69	  /** Validates the form: an invalid form shows every message and sends nothing. */
    70	  pay(): void {
    71	    const booking = this.bookings.read();
    72	    if (!booking || this.submitting()) {
    73	      return;
    74	    }
    75	    this.touched.set(new Set(CHECKOUT_FIELDS));
    76	    const values = this.values();
    77	    if (Object.keys(this.errors()).length > 0) {
    78	      this.toast.show('The form contains errors');
    79	      return;
    80	    }
    81	
    82	    const seats = ticketsFor(booking.seats).flatMap((item) => item.seatIds);
    83	    this.submitting.set(true);
    84	    this.api
    85	      .createReservation({
    86	        screeningId: booking.screeningId,
    87	        seats,
    88	        customer: {
    89	          firstName: values.firstName,
    90	          lastName: values.lastName,
    91	          email: values.email,
    92	          phone: values.phone,
    93	        },
    94	        totalPrice: this.total,
    95	      })
    96	      .subscribe({
    97	        next: () => {
    98	          this.bookings.write({ ...booking, checkout: values, paidEmail: values.email });
    99	          void this.router.navigate(['/confirmation']);
   100	        },
   101	        error: () => {
   102	          this.submitting.set(false);
   103	          this.toast.show('Payment failed. Please try again.');
   104	        },
   105	      });
   106	  }
   107	
   108	  back(): void {
   109	    const booking = this.bookings.read();
   110	    if (booking) {
   111	      void this.router.navigate(['/screenings', booking.screeningId, 'summary']);
   112	    }
   113	  }
   114	
   115	  private setValue<K extends keyof CheckoutValues>(field: K, value: CheckoutValues[K]): void {
   116	    const next = { ...this.values(), [field]: value };
   117	    this.values.set(next);
   118	    const booking = this.bookings.read();
   119	    if (booking) {
   120	      this.bookings.write({ ...booking, checkout: next });
   121	    }
   122	  }
   123	}
