    10	
    11	export type CheckoutField = keyof CheckoutValues;
    12	
    13	export type CheckoutErrors = Partial<Record<CheckoutField, string>>;
    14	
    15	export const CHECKOUT_FIELDS: readonly CheckoutField[] = [
    16	  'firstName',
    17	  'lastName',
    18	  'email',
    19	  'confirmEmail',
    20	  'phone',
    21	  'terms',
    22	];
    23	
    24	export const EMPTY_CHECKOUT: CheckoutValues = {
    25	  firstName: '',
    26	  lastName: '',
    27	  email: '',
    28	  confirmEmail: '',
    29	  phone: '',
    30	  terms: false,
    31	};
    32	
    33	/** A valid address: characters without spaces or `@`, `@`, then a domain with a dot inside. */
    34	const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    35	const PHONE_PATTERN = /^\d{9}$/;
    36	
    37	/** Returns the message of every failing field (section 7). Values are not trimmed. */
    38	export function validateCheckout(values: CheckoutValues): CheckoutErrors {
    39	  const errors: CheckoutErrors = {};
    40	
    41	  const firstNameError = nameError('First name', values.firstName);
    42	  if (firstNameError) {
    43	    errors.firstName = firstNameError;
    44	  }
    45	  const lastNameError = nameError('Last name', values.lastName);
    46	  if (lastNameError) {
    47	    errors.lastName = lastNameError;
    48	  }
    49	
    50	  if (values.email === '') {
    51	    errors.email = 'Email is required';
    52	  } else if (!EMAIL_PATTERN.test(values.email)) {
    53	    errors.email = 'Enter a valid email address';
    54	  }
    55	
    56	  if (values.confirmEmail === '') {
    57	    errors.confirmEmail = 'Confirm email is required';
    58	  } else if (values.confirmEmail !== values.email) {
    59	    errors.confirmEmail = 'Email addresses do not match';
    60	  }
    61	
    62	  if (values.phone !== '' && !PHONE_PATTERN.test(values.phone)) {
    63	    errors.phone = 'Phone number must be exactly 9 digits';
    64	  }
    65	
    66	  if (!values.terms) {
    67	    errors.terms = 'You must accept the terms and conditions';
    68	  }
    69	
    70	  return errors;
    71	}
    72	
    73	function nameError(label: string, value: string): string | null {
    74	  if (value === '') {
    75	    return `${label} is required`;
    76	  }
    77	  if (value.length < 2) {
    78	    return `${label} must be at least 2 characters`;
    79	  }
    80	  return null;
    81	}
